// Same layout as CryOmni3DEngine_Atlantis::SubjSprite / kSprTransp (engine.h).
struct SubjSprite {
	uint16 w, h;
	int16  xoff, yoff;
	Common::Array<uint16> pixels;
	Common::Array<uint8>  blend;
};
static const uint16 kSprTransp = 0x0001;

